"""Builds colab_training.ipynb: the whole training pipeline in one notebook for a Colab GPU."""
import nbformat as nbf
from notebook_tools import inline_modules

FILES = ["data.py", "features.py", "portfolio.py", "dataset.py", "model.py", "train.py", "backtest.py"]

nb = nbf.v4.new_notebook()
cells = [
    nbf.v4.new_markdown_cell(
        "# Momentum Transformer: Colab Training\n"
        "The complete pipeline (data download, features, model, training, backtest) in one notebook, "
        "for running on a Colab GPU. Generated by `create_colab.py` from the repo's modules."),
    nbf.v4.new_markdown_cell("## 1. Install Dependencies"),
    nbf.v4.new_code_cell("!pip install -q yfinance pandas numpy torch tqdm scipy"),
    nbf.v4.new_markdown_cell("## 2. All-in-One Source Code"),
    nbf.v4.new_code_cell(inline_modules(FILES)),
    nbf.v4.new_markdown_cell("## 3. Execute Pipeline\nDownload data, compute features, train (seeded), then backtest."),
    nbf.v4.new_code_cell(
        "import os\n"
        "\n"
        "df_raw = download_data(TICKERS, '2005-01-01', '2024-01-01', 'data/raw_data.csv')\n"
        "df_features = compute_features(df_raw)\n"
        "os.makedirs('data', exist_ok=True)\n"
        "df_features.to_csv('data/features.csv', index=False)\n"
        "print('Features:', df_features.shape)\n"
        "\n"
        "# Train with a fixed seed; repeat with other seeds to report mean +/- std\n"
        "train_model(seed=42)\n"
        "\n"
        "# Out-of-sample backtest (ex-ante leverage, TSMOM baseline, results/metrics.md)\n"
        "metrics, bench_metrics, port_returns, bench_returns = run_backtest()\n"),
]
nb['cells'] = cells
with open('colab_training.ipynb', 'w') as f:
    nbf.write(nb, f)
print("colab_training.ipynb created successfully.")
